import pulumi_atlasauth as atlas

this = atlas.SmsProvider("this", twilio={
    "account_sid": twilio_account_sid,
    "auth_token": twilio_auth_token,
    "from_": "+15555550100",
})
```
```csharp
using System.Collections.Generic;
using System.Linq;
